1	/**
2	 * StatusList2021 manager.
3	 * - Maintains a bitstring of revoked credential indices (stored in data/statuslist.json)
4	 * - Serves a signed StatusList2021 credential at /status/{listId}
5	 * - Each issued credential gets an index; revocation flips the bit
6	 * - Auto-refresh: re-signs and re-publishes the list on any revocation
7	 *
8	 * Spec: https://www.w3.org/TR/vc-status-list/
9	 */
10	import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'fs';
11	import { randomUUID } from 'crypto';
12	import { SignJWT } from 'jose';
13	import { getIssuerKeyPair } from '../keys/manager.js';
14	import { loadConfig } from '../config/loader.js';
15	
16	function getPaths() {
17	  const dataDir = process.env.DATA_DIR ?? './data';
18	  return {
19	    dataDir,
20	    statusPath: `${dataDir}/statuslist.json`,
21	  };
22	}
23	const LIST_SIZE = 131072; // 16KB bitstring = 131072 credential slots
24	
25	// Cache for the signed StatusList JWT to avoid re-signing on every request
26	let cachedStatusListJWT: { jwt: string; revokedIndicesHash: string; timestamp: number } | null = null;
27	const STATUSLIST_CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes cache TTL
28	
29	interface StatusListStore {
30	  listId: string;
31	  nextIndex: number;
32	  revokedIndices: number[];
33	  issuedCredentials: Array<{
34	    credentialId: string;
35	    holderEmail: string;
36	    statusIndex: number;
37	    issuedAt: string;
38	    revoked: boolean;
39	    revokedAt?: string;
40	  }>;
41	}
42	
43	function loadStore(): StatusListStore {
44	  const { dataDir, statusPath } = getPaths();
45	  if (!existsSync(dataDir)) mkdirSync(dataDir, { recursive: true });
46	  if (existsSync(statusPath)) {
47	    return JSON.parse(readFileSync(statusPath, 'utf-8')) as StatusListStore;
48	  }
49	  const store: StatusListStore = {
50	    listId: randomUUID(),
51	    nextIndex: 0,
52	    revokedIndices: [],
53	    issuedCredentials: [],
54	  };
55	  writeFileSync(statusPath, JSON.stringify(store, null, 2));
56	  return store;
57	}
58	
59	function saveStore(store: StatusListStore): void {
60	  const { statusPath } = getPaths();
61	  writeFileSync(statusPath, JSON.stringify(store, null, 2));
62	}
63	
64	function buildBitstring(revokedIndices: number[]): string {
65	  const bytes = new Uint8Array(Math.ceil(LIST_SIZE / 8));
66	  for (const idx of revokedIndices) {
67	    const byteIndex = Math.floor(idx / 8);
68	    const bitIndex = idx % 8;
69	    bytes[byteIndex] |= (1 << bitIndex);
70	  }
71	  return Buffer.from(bytes).toString('base64url');
72	}
