116	/** Get all issued credentials for admin view. */
117	export function getIssuedCredentials() {
118	  return loadStore().issuedCredentials;
119	}
120	
121	/** Search issued credentials by various criteria. */
122	export function searchCredentials(query: string): StatusListStore['issuedCredentials'] {
123	  const store = loadStore();
124	  const q = query.toLowerCase().trim();
125	  
126	  if (!q) {
127	    return store.issuedCredentials;
128	  }
129	
130	  return store.issuedCredentials.filter(cred => {
131	    // Search by credential ID
132	    if (cred.credentialId.toLowerCase().includes(q)) return true;
133	    
134	    // Search by holder email
135	    if (cred.holderEmail.toLowerCase().includes(q)) return true;
136	    
137	    // Search by status
138	    if (cred.revoked && q.includes('revoked')) return true;
139	    if (!cred.revoked && q.includes('active')) return true;
140	    
141	    // Search by date (issuedAt)
142	    if (cred.issuedAt && cred.issuedAt.toLowerCase().includes(q)) return true;
143	    
144	    // Search by revokedAt
145	    if (cred.revokedAt && cred.revokedAt.toLowerCase().includes(q)) return true;
146	    
147	    return false;
148	  });
149	}
