19	function pairwisePseudonym(secret: string, thumbprint: string, issuer: string, type: string): string {
20	  return 'did:askmi:pairwise:' + createHmac('sha256', secret)
21	    .update(thumbprint + '|' + issuer + '|' + type)
22	    .digest('base64url');
23	}
