25	export function resolveMappedData(
26	  template: CredentialTemplate,
27	  fieldMappings: Record<string, string>,
28	  holderData: Record<string, unknown>
29	): { mappedData: Record<string, unknown>; errors: string[] } {
30	  const mappedData: Record<string, unknown> = {};
31	  const errors: string[] = [];
32	
33	  const normalize = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, '');
34	
35	  const templateFields = [...template.requiredFields, ...template.optionalFields];
36	
37	  for (const templateField of templateFields) {
38	    // 1. Try explicit mapping from config
39	    const explicitSourceField = fieldMappings[templateField];
40	    if (explicitSourceField && holderData[explicitSourceField] !== undefined) {
41	      mappedData[templateField] = holderData[explicitSourceField];
42	      continue;
43	    }
44	
45	    // 2. Fallback: try direct match (no mapping required if key matches exactly)
46	    if (holderData[templateField] !== undefined) {
47	      mappedData[templateField] = holderData[templateField];
48	      continue;
49	    }
50	
51	    // 3. Fallback: smart camelCase/snake_case/case-insensitive match
52	    const normTemplate = normalize(templateField);
53	    let matched = false;
54	    for (const k of Object.keys(holderData)) {
55	      if (normalize(k) === normTemplate) {
56	        mappedData[templateField] = holderData[k];
57	        matched = true;
58	        break;
59	      }
60	    }
61	
62	    // 4. Validate if required field is still missing
63	    if (!matched && template.requiredFields.includes(templateField)) {
64	      errors.push(`Required field "${templateField}" could not be resolved from holder data`);
65	    }
66	  }
67	
68	  return { mappedData, errors };
69	}
